mapper.select:
select lati.id, lati.name, lati.icon, lati.type, lati.create_user_id, lati.update_user_id, lati.create_time, lati.update_time from la_activity_task_item lati
and lati.is_delete = 0
and lati.name like concat('%',#{param.name},'%')
and lati.icon like concat('%',#{param.icon},'%')
and lati.type = #{param.type}
and lati.create_user_id = #{param.createUserId}
and lati.update_user_id = #{param.updateUserId}
order by lati.id desc
